CREATE TABLE companies (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(180) NOT NULL, active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE plants (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, company_id BIGINT UNSIGNED NOT NULL, name VARCHAR(180) NOT NULL, active TINYINT(1) NOT NULL DEFAULT 1, FOREIGN KEY(company_id) REFERENCES companies(id)) ENGINE=InnoDB;
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, company_id BIGINT UNSIGNED NULL, first_name VARCHAR(100) NOT NULL, last_name VARCHAR(100) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('admin','operator','client') NOT NULL, admin_slot TINYINT GENERATED ALWAYS AS (CASE WHEN role='admin' THEN 1 ELSE NULL END) STORED, UNIQUE KEY one_admin (admin_slot), CONSTRAINT only_owner_admin CHECK ((role='admin' AND email='caniatoa@libero.it') OR (role<>'admin' AND email<>'caniatoa@libero.it')), active TINYINT(1) NOT NULL DEFAULT 1, session_version INT UNSIGNED NOT NULL DEFAULT 0, privacy_version VARCHAR(40) NULL, privacy_accepted_at DATETIME NULL, deleted_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(company_id) REFERENCES companies(id)) ENGINE=InnoDB;
CREATE TABLE user_plants (user_id BIGINT UNSIGNED NOT NULL, plant_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(user_id,plant_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(plant_id) REFERENCES plants(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE documents (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, company_id BIGINT UNSIGNED NOT NULL, plant_id BIGINT UNSIGNED NOT NULL, recipient_id BIGINT UNSIGNED NOT NULL, title VARCHAR(220) NOT NULL, original_name VARCHAR(255) NOT NULL, storage_key CHAR(64) NOT NULL UNIQUE, mime VARCHAR(120) NOT NULL, bytes BIGINT UNSIGNED NOT NULL, sha256 CHAR(64) NOT NULL, created_by BIGINT UNSIGNED NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, first_download_at DATETIME NULL, download_count INT UNSIGNED NOT NULL DEFAULT 0, revoked_at DATETIME NULL, deleted_at DATETIME NULL, INDEX(created_at), INDEX(recipient_id,first_download_at), FOREIGN KEY(company_id) REFERENCES companies(id), FOREIGN KEY(plant_id) REFERENCES plants(id), FOREIGN KEY(recipient_id) REFERENCES users(id), FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE download_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, document_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, started_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, ip VARBINARY(16) NULL, INDEX(started_at), FOREIGN KEY(document_id) REFERENCES documents(id), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE notification_queue (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, kind VARCHAR(32) NOT NULL, recipient_email VARCHAR(254) NOT NULL, subject VARCHAR(255) NOT NULL, body TEXT NOT NULL, attempts SMALLINT UNSIGNED NOT NULL DEFAULT 0, next_attempt_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, sent_at DATETIME NULL, error TEXT NULL, dedupe_key VARCHAR(150) NOT NULL UNIQUE, INDEX(sent_at,next_attempt_at)) ENGINE=InnoDB;
CREATE TABLE audit_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, actor_id BIGINT UNSIGNED NOT NULL, action VARCHAR(60) NOT NULL, subject_id BIGINT UNSIGNED NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(created_at), FOREIGN KEY(actor_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE login_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, email VARCHAR(254) NOT NULL, ip VARBINARY(16) NULL, occurred_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(email,occurred_at)) ENGINE=InnoDB;
CREATE TABLE alerts (alert_key VARCHAR(80) PRIMARY KEY, active TINYINT(1) NOT NULL DEFAULT 0, changed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE password_reset_tokens (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expires_at DATETIME NOT NULL, used_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(user_id,created_at), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE access_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, ip VARBINARY(16) NULL, user_agent VARCHAR(500) NULL, occurred_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(user_id,occurred_at), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE portal_settings (setting_key VARCHAR(40) PRIMARY KEY, value_int INT UNSIGNED NOT NULL DEFAULT 0) ENGINE=InnoDB;
INSERT INTO portal_settings(setting_key,value_int) VALUES ('max_downloads',0),('retention_days',0);
